import{B as e,et as t,mt as n,tt as r}from"./chunks/framework.Bgbhl1zx.js";var i=JSON.parse(`{"title":"Claude Code Mods","description":"Claude Code의 UI를 변경할 수 있는 모드에 대해서 알아봅니다.","frontmatter":{"title":"Claude Code Mods","date":"2026-10-21T07:00+09:00","description":"Claude Code의 UI를 변경할 수 있는 모드에 대해서 알아봅니다.","tags":["Claude Code","Mod","플러그인"]},"headers":[],"relativePath":"posts/claude-code-mods.md","filePath":"posts/claude-code-mods.md","lastUpdated":1792708998000}`),a={name:`posts/claude-code-mods.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="claude-code-mods" tabindex="-1">Claude Code Mods <a class="header-anchor" href="#claude-code-mods" aria-label="Permalink to “Claude Code Mods”">​</a></h1><p>Claude Code에 일부 UI를 변경할 수 있는 <a href="https://code.claude.com/docs/ko/plugins/mods/overview" target="_blank" rel="noreferrer">모드(Mods)</a> 기능이 추가되었다.</p><p><a href="https://news.hada.io/topic?id=34796" target="_blank" rel="noreferrer">긱뉴스에 소개</a>되고 2주나 지났지만, 솔직히 아직까지는 딱히 유용해 보이는 모드가 눈에 띄지 않는다. 모드는 터미널과 클로드 데스크톱 앱에서 지원한다.</p><h2 id="token-weather" tabindex="-1">Token Weather <a class="header-anchor" href="#token-weather" aria-label="Permalink to “Token Weather”">​</a></h2><p>공개된 샘플 모드들 중에서는 그나마 <a href="https://github.com/anthropics/claude-code-playground/tree/main/claude-code/mods/token-weather" target="_blank" rel="noreferrer">Token Weather</a> 정도가 써볼 만하다.</p><p>프롬프트 바로 위에 현재 컨텍스트 사용량과 최근 턴의 토큰 증감을 작은 차트와 날씨 아이콘으로 보여주어, 세션 정리나 압축 타이밍을 직관적으로 파악하기 좋다.</p><h2 id="you-should-know" tabindex="-1">You should know <a class="header-anchor" href="#you-should-know" aria-label="Permalink to “You should know”">​</a></h2><p>Claude Code의 <a href="https://code.claude.com/docs/ko/plugins/mods/overview#mods-built-into-claude-code" target="_blank" rel="noreferrer">내장 모드 목록</a>을 보면 기본적으로 비활성화되어 있는 숨겨진 모드가 있다. 바로 <code>cc-plugin-you-should-know</code>다.</p><p>보조 에이전트가 백그라운드에서 대화 맥락을 읽다가 사용자가 놓쳤을 수 있는 중요한 내용을 발견하면 프롬프트 위에 짧은 알림을 띄워주는 기능이다. 필요하다면 프롬프트에서 직접 켜서 사용할 수 있다.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cc-plugin-you-should-know@builtin</span></span></code></pre></div><h2 id="나의-모드-만들기" tabindex="-1">나의 모드 만들기 <a class="header-anchor" href="#나의-모드-만들기" aria-label="Permalink to “나의 모드 만들기”">​</a></h2><p>본인만의 아이디어가 있다면 <a href="https://code.claude.com/docs/ko/plugins/mods/create#ask-claude-for-a-mod" target="_blank" rel="noreferrer">대화창에서 Claude에게 모드를 만들어달라고 설명</a>하면 된다.</p><p>이때 <code>cc-plugin-plugin-authoring</code>을 사용해서 모드를 만들기 위한 스킬을 설치한다. 먼저 세션에서 바로 동작할 수 있게 핫 리로드 방식으로 보여주며, 마음에 들면 플러그인 방식으로 설치할 수 있다.</p><p>나는 딱히 아이디어가 떠오르지 않아서 아무래도 사용하지 않을 것 같다.</p>`,14)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};